mapper.select:
SELECT id, name, description, display_order, is_active
FROM categories
WHERE id = #{id}

SELECT id, name, description, display_order, is_active
FROM categories
WHERE name = #{name}

SELECT id, name, description, display_order, is_active
FROM categories

    ORDER BY ${orderBy}


    ORDER BY display_order ASC, id ASC

LIMIT #{limit} OFFSET #{offset}

SELECT id, name, description, display_order, is_active
FROM categories
WHERE is_active = true

    ORDER BY ${orderBy}


    ORDER BY display_order ASC, id ASC

LIMIT #{limit} OFFSET #{offset}
